CREATE TEMP TABLE conflict_targets ON COMMIT DROP AS
SELECT s.id, ci.block, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'sortOrder', s.sort_order, 'name', s.name,
    'contactPerson', s.contact_person, 'email', s.email, 'phone', s.phone, 'description', s.description,
    'deadline', s.deadline, 'activities', s.activities, 'interests', s.interests, 'status', s.status,
    'statusChangedBy', s.status_changed_by, 'statusChangedAt', CASE WHEN s.status_changed_at IS NULL THEN NULL ELSE to_char(s.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', s.version, 'deletedAt', CASE WHEN s.deleted_at IS NULL THEN NULL ELSE to_char(s.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN s.created_at IS NULL THEN NULL ELSE to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN s.updated_at IS NULL THEN NULL ELSE to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) AS before
FROM conflict_import ci
JOIN projects p ON p.name = 'Sjabloon – Stakeholders per fase' AND p.deleted_at IS NULL
JOIN phases f ON f.project_id = p.id AND f.name = ci.phase_name AND f.deleted_at IS NULL
JOIN stakeholders s ON s.phase_id = f.id AND s.name = ci.stakeholder_name AND s.deleted_at IS NULL;

DO $$
DECLARE expected int; found int;
BEGIN
  SELECT count(*) INTO expected FROM conflict_import;
  SELECT count(*) INTO found FROM conflict_targets;
  IF found <> expected THEN
    RAISE EXCEPTION 'Verwachtte % stakeholders, gevonden %. Is het project of een stakeholder hernoemd of verwijderd? Er is niets aangepast.', expected, found;
  END IF;
  IF EXISTS (SELECT 1 FROM stakeholders s JOIN conflict_targets t ON t.id = s.id WHERE s.interests LIKE '%BELANGENCONFLICTEN (bron: Belangenverstrengeling_per_fase_woningbouw.xlsx)%') THEN
    RAISE EXCEPTION 'Deze belangenconflicten zijn al toegevoegd. Er is niets aangepast.';
  END IF;
END $$;

UPDATE stakeholders s
SET interests = CASE WHEN s.interests = '' THEN t.block ELSE s.interests || E'\n\n' || t.block END,
    version = s.version + 1,
    updated_at = now()
FROM conflict_targets t
WHERE s.id = t.id;

-- Version history: one "update" event per stakeholder, all in one batch.
INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT s.project_id, 'stakeholder', s.id, 'update', t.before, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'sortOrder', s.sort_order, 'name', s.name,
    'contactPerson', s.contact_person, 'email', s.email, 'phone', s.phone, 'description', s.description,
    'deadline', s.deadline, 'activities', s.activities, 'interests', s.interests, 'status', s.status,
    'statusChangedBy', s.status_changed_by, 'statusChangedAt', CASE WHEN s.status_changed_at IS NULL THEN NULL ELSE to_char(s.status_changed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'version', s.version, 'deletedAt', CASE WHEN s.deleted_at IS NULL THEN NULL ELSE to_char(s.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN s.created_at IS NULL THEN NULL ELSE to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN s.updated_at IS NULL THEN NULL ELSE to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END),
       (SELECT id FROM users WHERE role = 'admin' AND status = 'active' ORDER BY created_at LIMIT 1),
       b.batch_id, 'Belangenconflicten toegevoegd uit Excel: Belangenverstrengeling_per_fase_woningbouw.xlsx'
FROM stakeholders s
JOIN conflict_targets t ON t.id = s.id
CROSS JOIN (SELECT gen_random_uuid() AS batch_id) b
JOIN phases f ON f.id = s.phase_id
ORDER BY f.sort_order, s.sort_order;

COMMIT;
